import sys, math, os
from io import BytesIO, IOBase
from bisect import bisect_left as bl, bisect_right as br, insort
from collections import defaultdict as dd, deque, Counter

def data():
	return sys.stdin.readline().strip()

def mdata():
	return list(map(int, data().split()))

def outl(var):
	sys.stdout.write(' '.join(map(str, var)) + '\n')

def out(var):
	sys.stdout.write(str(var) + '\n')
sys.setrecursionlimit(100000)
from fractions import Fraction
INF = float('inf')
mod = 998244353

def main():
	for t in range(int(data())):
		(h, c, t) = mdata()
		if (h + c) / 2 >= t:
			out(2)
			continue
		if t == h:
			out(1)
			continue
		k = int((h - t) // abs((h + c) / 2 - t))
		k -= 2
		if k % 2 != 0:
			k -= 1
		k = max(0, k)
		if Fraction(abs(2 * t * (k + 5) - ((k + 4) * (h + c) + 2 * h)), k + 5) < Fraction(abs(2 * t * (k + 1) - (k * (h + c) + 2 * h)), k + 1) and Fraction(abs(2 * t * (k + 5) - ((k + 4) * (h + c) + 2 * h)), k + 5) < Fraction(abs(2 * t * (k + 3) - ((k + 2) * (h + c) + 2 * h)), k + 3):
			out(k + 5)
		elif Fraction(abs(2 * t * (k + 1) - (k * (h + c) + 2 * h)), k + 1) <= Fraction(abs(2 * t * (k + 3) - ((k + 2) * (h + c) + 2 * h)), k + 3):
			out(k + 1)
		else:
			out(k + 3)
main()
